from pathlib import Path
from datetime import date
from dotenv import load_dotenv
import anthropic
import streamlit as st

# Load the API key from the .env file
load_dotenv()

# Page title and description
st.set_page_config(page_title="Regulatory Change Summarizer", layout="wide")
st.title("Regulatory Change Summarizer")
st.caption(
    "Paste a CFPB rule or notice to get an impact summary for a U.S. mortgage "
    "servicer. Output is generated by AI from the text provided and is not legal advice."
)

# Read the briefing
system_prompt = Path("system_prompt.md").read_text(encoding="utf-8")

# Servicer profile dropdowns, side by side
col1, col2 = st.columns(2)
with col1:
    institution = st.selectbox(
        "Institution type", ["Bank or credit union", "Nonbank servicer"]
    )
with col2:
    size = st.selectbox(
        "Portfolio size", ["More than 5,000 loans", "5,000 loans or fewer"]
    )

# Box for pasting the document
notice_text = st.text_area("Paste the regulatory document text", height=300)

# When the button is clicked
if st.button("Summarize"):
    # Basic input checks, which also control cost
    if len(notice_text.strip()) < 200:
        st.warning("This looks too short to analyze. Please paste the full document text.")
    elif len(notice_text) > 100000:
        st.warning("This document is too long for this demo. Please paste a shorter section.")
    else:
        profile = f"Servicer profile:\n- Institution type: {institution}\n- Portfolio size: {size}"
        today = date.today().strftime("%B %d, %Y")

        client = anthropic.Anthropic()
        with st.spinner("Reading the document. This takes about 30 seconds..."):
            response = client.messages.create(
                model="claude-sonnet-5-5",
                max_tokens=4000,
                system=system_prompt,
                messages=[
                    {
                        "role": "user",
                        "content": f"Today's date: {today}\n\n{profile}\n\n<document>\n{notice_text}\n</document>",
                    }
                ],
            )

        # Show the answer, skipping the reasoning blocks
        for block in response.content:
            if block.type == "text":
                st.markdown(block.text)